export function StaleState({
  label = "{{label}}",
  value = "{{value}}",
  accent = "{{accent}}",
  force = {{force}},
}) {
  return (
    <div style={{ width: 260, boxSizing: "border-box", font: "14px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: "16px 18px", borderRadius: 12, borderLeft: `4px solid ${force ? accent : "transparent"}` }}>
      <p style={{ margin: "0 0 4px", fontSize: 11, fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.04em", color: "#241430888" }}>{label}</p>
      <p style={{ margin: "0 0 6px", fontSize: 18, fontWeight: 700, opacity: force ? 0.6 : 1 }}>{value}</p>
      <p style={{ margin: 0, fontSize: 11, color: "#241430888", display: "flex", alignItems: "center", gap: 6 }}>
        Updated <time dateTime="2026-08-11T09:00:00Z">7 days ago</time>
        {force && <span style={{ background: accent, color: "#241430", fontWeight: 700, padding: "1px 7px", borderRadius: 999, fontSize: 10, textTransform: "uppercase" }}>stale</span>}
      </p>
    </div>
  );
}
